const repo = '/home/apnex/taceng/context-lab';
const exported = '/tmp/agp-evaluator-compatibility.t27xtR/context-lab';
const agp = '/home/apnex/taceng/agp';
const revisions = {
  frozen: '6e6d0a92965a15ec473c661887b2b9c5037fedcf',
  firstCap: '9a9b5e96c484b37d3f3fdbf34c0e7b726747a0a1',
  parentCandidate: 'e705b3d749400d0a79efe98e5338e9c84a1695b8',
  observedTip: '0c0ab1f0248ef0cbb21885d7d6af76586d8a1b68',
};
const git = (...args) => execFileSync('git', ['-C', repo, ...args], { encoding: 'utf8' });
const sha256 = (value) => createHash('sha256').update(value).digest('hex');
const checks = [];
const verified = (name, check) => { check(); checks.push(name); };
const files = git('ls-tree', '-r', '--name-only', revisions.parentCandidate).trim().split('\n');
verified('All exported tracked bytes match the exact parent candidate', () => {
  assert.equal(fs.existsSync(path.join(exported, '.git')), false);
  assert.notEqual(fs.realpathSync(exported), fs.realpathSync(repo));
  for (const file of files) {
    assert.deepEqual(fs.readFileSync(path.join(exported, file)),
      execFileSync('git', ['-C', repo, 'show', revisions.parentCandidate + ':' + file]));
  }
});
const changedSource = git('diff', '--name-only', revisions.parentCandidate, revisions.observedTip, '--', 'packages/core/src').trim().split('\n');
verified('Only adapters and isolation prober differ from the observed tip source', () => {
  assert.deepEqual(changedSource, ['packages/core/src/adapters.ts', 'packages/core/src/isolation-prober.ts']);
});
const paths = files.filter((file) => file.startsWith('packages/core/src/'));
const sourceBlobs = paths.map((file) => ({
  file,
  ...Object.fromEntries(Object.entries(revisions).map(([name, revision]) =>
    [name, git('rev-parse', revision + ':' + file).trim()])),
}));
verified('Parent probe is byte-identical to the frozen evaluator probe', () => {
  const probe = sourceBlobs.find((row) => row.file.endsWith('/isolation-prober.ts'));
  assert.equal(probe.parentCandidate, probe.frozen);
});
verified('Parent adapter is byte-identical to the first public-cap adapter', () => {
  const adapter = sourceBlobs.find((row) => row.file.endsWith('/adapters.ts'));
  assert.equal(adapter.parentCandidate, adapter.firstCap);
});
verified('Parent and tip dependency declarations and lock are identical', () => {
  assert.equal(git('diff', revisions.parentCandidate, revisions.observedTip, '--',
    'package.json', 'package-lock.json', 'packages/core/package.json'), '');
});
const buildOutput = execFileSync('npm', ['run', 'build', '--', '--force'], { cwd: exported, encoding: 'utf8' });
checks.push('Forced isolated TypeScript build completed');
const core = await import(pathToFileURL(path.join(exported, 'packages/core/dist/src/index.js')).href);
const packPath = path.join(agp, 'docs/reviews/admission-lifetime-assurance-r4/pack.json');
const packText = fs.readFileSync(packPath, 'utf8');
const pack = JSON.parse(packText);
const experimentPath = path.join(path.dirname(packPath), pack.experiments[0]);
const experimentText = fs.readFileSync(experimentPath, 'utf8');
const experiment = JSON.parse(experimentText);
verified('Current two AGP arms use only instruction delivery and no hooks', () => {
  assert.equal(pack.arms.length, 2);
  assert.ok(pack.arms.every((arm) => arm.deliver.length > 0 && arm.deliver.every((d) => d.as === 'instruction')));
  assert.deepEqual(pack.hooks, []);
  assert.deepEqual(core.EMPTY_ARM.onRequest, []);
});
verified('Current AGP experiment declares a single new-session answer phase', () => {
  assert.deepEqual(experiment.phases, [{ id: 'answer', session: 'new' }]);
});
const runtime = core.opencodeAdapter({
  operatorConfig: path.join(agp, 'docs/reviews/admission-lifetime-assurance-r4/admission-provider-config.json'),
  env: {}, binary: '/not-invoked/opencode', operatorCache: '/not-read/cache',
});
const member = structuredClone(pack.population.find((m) => m.id === 'g'));
member.settings = { outputTokenMax: 4096 };
const invocation = {
  member, arm: core.EMPTY_ARM, mode: 'attachment', tools: 'off', prompt: '',
  workspace: exported, work: '/not-created/invocation', timeLimitSeconds: 1,
};
verified('Parent public refusal accepts a positive integer test cap without invoking a runtime', () => {
  assert.equal(runtime.refuse(invocation), null);
});
const route = runtime.route(member);
verified('Parent declared route reports the test cap and configured model limit', () => {
  assert.equal(route.memberSettings.outputTokenMax, 4096);
  assert.equal(route.settings.limit.output, 65536);
  assert.equal(route.npm, '@ai-sdk/openai-compatible');
  assert.equal('apiKey' in route.endpoint, false);
  assert.equal('headers' in route.endpoint, false);
});
const codex = core.codexAdapter({ env: {}, vendor: '/not-invoked/codex', models: '/not-read/models', auth: '/not-read/auth' });
verified('Parent public refusal rejects the cap for Codex without invoking a runtime', () => {
  assert.match(codex.refuse({ ...invocation, mode: 'stdin', member: { ...pack.population.find((m) => m.id === 'o'), settings: { outputTokenMax: 4096 } } }), /outputTokenMax.*not one Codex can apply/);
});
const preservationPaths = [
  'docs/reviews/admission-evaluation-preparation',
  'docs/reviews/admission-lifetime-assurance',
  'docs/reviews/admission-lifetime-assurance-r4',
  'docs/reviews/admission-lifetime-correction-r4.md', 'packages', 'cli',
];
verified('Reviewed packets and AGP code have no delta against this turn starting HEAD', () => {
  assert.equal(execFileSync('git', ['-C', agp, 'diff', '--name-only', '0e4fb13921626d91199aadb508145c5d9d54cd47', '--', ...preservationPaths], { encoding: 'utf8' }), '');
});
const result = {
